<?php
namespace App\Services;use App\Models\AccessPoint;use App\Models\SystemThreshold;use Carbon\CarbonInterface;
class CongestionAnalysisService{
 public function analyse(AccessPoint $ap,CarbonInterface $from,CarbonInterface $to):array{$samples=$ap->loadSamples()->whereBetween('sampled_at',[$from,$to])->get();if($samples->isEmpty())return['classification'=>'insufficient_evidence','severity'=>'unknown','evidence'=>[],'limitations'=>['No AP-load telemetry is available for this period.']];$util=$this->median($samples->pluck('channel_utilisation_percent')->filter(fn($v)=>$v!==null));$clients=$this->median($samples->pluck('connected_clients')->filter(fn($v)=>$v!==null));$lat=$this->median($samples->pluck('latency_ms')->filter(fn($v)=>$v!==null));$loss=$this->median($samples->pluck('packet_loss_percent')->filter(fn($v)=>$v!==null));$throughput=$this->median($samples->pluck('throughput_mbps')->filter(fn($v)=>$v!==null));$utilHigh=$util!==null&&$util>SystemThreshold::number('channel_utilisation_high_percent',70);$clientLimit=$ap->configured_client_limit??50;$clientsHigh=$clients!==null&&$clients>$clientLimit;$performanceBad=($lat!==null&&$lat>SystemThreshold::number('latency_poor_ms',100))||($loss!==null&&$loss>SystemThreshold::number('packet_loss_poor_percent',3))||($throughput!==null&&$throughput<SystemThreshold::number('throughput_poor_mbps',10));$classification=$utilHigh&&$clientsHigh&&$performanceBad?'possible_congestion':'no_congestion_evidence';$limitations=[];if($util===null)$limitations[]='Channel utilisation is unavailable.';if($clients===null)$limitations[]='Connected-client count is unavailable.';if($lat===null&&$loss===null&&$throughput===null)$limitations[]='Performance evidence is unavailable.';return['classification'=>$classification,'severity'=>$classification==='possible_congestion'?'high':'low','evidence'=>['median_channel_utilisation_percent'=>$util,'median_connected_clients'=>$clients,'configured_client_limit'=>$clientLimit,'median_latency_ms'=>$lat,'median_packet_loss_percent'=>$loss,'median_throughput_mbps'=>$throughput,'sample_count'=>$samples->count()],'rule'=>'LOAD-001','limitations'=>$limitations];}
 private function median($c):?float{if($c->isEmpty())return null;$s=$c->map(fn($v)=>(float)$v)->sort()->values();$n=$s->count();return round($n%2?$s[intdiv($n,2)]:($s[$n/2-1]+$s[$n/2])/2,3);}}
